167:     assert.equal(new ConstantNode('hi', 'string').toString(), '"hi"');
168:     assert.equal(new ConstantNode('true', 'boolean').toString(), 'true');
169:     assert.equal(new ConstantNode('false', 'boolean').toString(), 'false');
170:     assert.equal(new ConstantNode('undefined', 'undefined').toString(), 'undefined');
171:     assert.equal(new ConstantNode('null', 'null').toString(), 'null');
172:   });
173: 
