175:     //Also checks if the custom functions get passed on to the children
176:     var customFunction = function (node, options) {
177:       if (node.type === 'ConstantNode') {
178:         return 'const(' + node.value + ', ' + node.valueType + ')'
179:       }
180:     };
181: 
182:     var n = new ConstantNode(1);
183: 
184:     assert.equal(n.toString({handler: customFunction}), 'const(1, number)');
185:   });
186: 
187:   it ('should LaTeX a ConstantNode', function () {
188:     assert.equal(new ConstantNode('3', 'number').toTex(), '3');
189:     assert.deepEqual(new ConstantNode('3', 'number').toTex(), '3');
190:     assert.equal(new ConstantNode('hi', 'string').toTex(), '\\mathtt{"hi"}');
191:     assert.equal(new ConstantNode('true', 'boolean').toTex(), 'true');
192:     assert.equal(new ConstantNode('false', 'boolean').toTex(), 'false');
193:     assert.equal(new ConstantNode('undefined', 'undefined').toTex(), 'undefined');
194:     assert.equal(new ConstantNode('null', 'null').toTex(), 'null');
195:   });
196: 
197:   it ('should LaTeX a ConstantNode in exponential notation', function () {
198:     var n = new ConstantNode('1e10', 'number');
199:     assert.equal(n.toTex(), '1\\cdot10^{10}');
200:   });
201: 
202:   it ('should LaTeX a ConstantNode with custom toTex', function () {
203:     //Also checks if the custom functions get passed on to the children
204:     var customFunction = function (node, options) {
205:       if (node.type === 'ConstantNode') {
